const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const SECTIONS=['inicio','conceptos','simulador','comprobacion','recursos','cierre'];
let conceptIndex=0,resourceContext=null,currentUtter=null,toneCtx=null;
const state={section:'inicio',font:1,sound:true,layout:'auto',theme:'light',concepts:{},quizOrder:[],quizIndex:0,quizStates:{},quizScore:0,lab:null};

function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d;}
function money(v){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',maximumFractionDigits:0}).format(Number(v)||0);}
function fmt(v,d=2){return Number.isFinite(v)?Number(v).toFixed(d):'—';}
function pct(v,d=1){return Number.isFinite(v)?`${(v*100).toFixed(d)}%`:'—';}
function randomInt(max){if(max<=1)return 0;try{if(window.crypto?.getRandomValues){const limit=Math.floor(0x100000000/max)*max,buf=new Uint32Array(1);let x;do{window.crypto.getRandomValues(buf);x=buf[0];}while(x>=limit);return x%max;}}catch(e){}return Math.floor(Math.random()*max);}
function shuffleIndices(len){const a=[...Array(len).keys()];for(let i=a.length-1;i>0;i--){const j=randomInt(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
function balancedPositions(items){const total=items.length;if(!total)return[];const optCount=Math.min(...items.map(x=>x.options.length));for(let attempt=0;attempt<1000;attempt++){const p=Array.from({length:total},()=>randomInt(optCount));const counts=Array(optCount).fill(0);p.forEach(x=>counts[x]++);const max=Math.max(...counts),unique=counts.filter(Boolean).length,maxAllowed=Math.max(1,Math.ceil(total/3));if(max<=maxAllowed&&unique>=Math.min(3,total,optCount))return p;}return shuffleIndices(total).map((_,i)=>i%optCount);}
let conceptCorrectPositions=balancedPositions(DATA.concepts),quizCorrectPositions=balancedPositions(DATA.quiz);
function orderWithTarget(q,target){const correct=q.options.findIndex(x=>x[1]);const others=shuffleIndices(q.options.length).filter(i=>i!==correct);others.splice(Math.min(target,others.length),0,correct);return others;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._tm);t._tm=setTimeout(()=>t.classList.remove('show'),2100);}
function beep(kind='ok'){if(!state.sound)return;try{toneCtx=toneCtx||new (window.AudioContext||window.webkitAudioContext)();const o=toneCtx.createOscillator(),g=toneCtx.createGain();o.frequency.value=kind==='bad'?220:kind==='soft'?430:650;g.gain.setValueAtTime(.0001,toneCtx.currentTime);g.gain.exponentialRampToValueAtTime(.05,toneCtx.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,toneCtx.currentTime+.10);o.connect(g);g.connect(toneCtx.destination);o.start();o.stop(toneCtx.currentTime+.11);}catch(e){}}

function go(section){if(!SECTIONS.includes(section))return;closeAllDialogs();state.section=section;$$('.section').forEach(s=>s.classList.toggle('active',s.id===section));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.go===section));window.scrollTo({top:0,behavior:'smooth'});if(section==='conceptos')renderConceptCards();if(section==='simulador')renderLab();if(section==='comprobacion')ensureQuiz();if(section==='recursos')renderResources();}
function openDialog(id){const d=$('#'+id);if(!d)return;try{if(!d.open)d.showModal();document.body.classList.add('dialog-open');}catch(e){d.setAttribute('open','');document.body.classList.add('dialog-open');}}
function closeDialog(id){const d=$('#'+id);if(!d)return;stopSpeech();$$('audio,video',d).forEach(m=>{try{m.pause();}catch(e){}});try{if(d.open)d.close();}catch(e){d.removeAttribute('open');}if(!$$('dialog[open]').length)document.body.classList.remove('dialog-open');}
function closeAllDialogs(){$$('dialog[open]').forEach(d=>closeDialog(d.id));}
function toggleFullscreen(el){if(!document.fullscreenElement){el.requestFullscreen?.().catch(()=>{});}else document.exitFullscreen?.().catch(()=>{});}
function applyLayout(){let active=state.layout;if(active==='auto')active=innerWidth/Math.max(innerHeight,1)>1.5?'16x9':'4x3';document.documentElement.dataset.layoutActive=active;document.documentElement.dataset.layoutMode=state.layout;$('#layoutSelect').value=state.layout;}
function updateFont(){document.documentElement.style.setProperty('--font-scale',state.font.toFixed(2));}
function applyTheme(){document.documentElement.dataset.theme=state.theme;const b=$('#themeBtn');b.textContent=state.theme==='dark'?'☀':'◐';b.setAttribute('aria-pressed',state.theme==='dark'?'true':'false');}

/* speech */
function pickVoice(){const vs=speechSynthesis.getVoices?.()||[];for(const lang of ['es-PE','es-419','es-MX','es-US','es']){const v=vs.find(x=>(x.lang||'').toLowerCase()===lang.toLowerCase())||vs.find(x=>(x.lang||'').toLowerCase().startsWith(lang.toLowerCase()));if(v)return v;}return vs.find(x=>(x.lang||'').toLowerCase().startsWith('es'))||null;}
function speak(text){if(!text||!('speechSynthesis'in window))return;stopSpeech();currentUtter=new SpeechSynthesisUtterance(text);currentUtter.lang='es-PE';const v=pickVoice();if(v)currentUtter.voice=v;currentUtter.rate=.96;speechSynthesis.speak(currentUtter);}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel();currentUtter=null;} function pauseSpeech(){speechSynthesis?.pause?.();} function resumeSpeech(){speechSynthesis?.resume?.();}
function speechControlsHTML(){return `<div class="speech-controls"><button type="button" data-speech="read">▶ Leer</button><button type="button" data-speech="explain">💡 Explicar</button><button type="button" data-speech="pause">Ⅱ Pausar</button><button type="button" data-speech="resume">↻ Continuar</button><button type="button" data-speech="stop">■ Detener</button></div>`;}
function bindSpeechControls(root,getText){$$('[data-speech]',root).forEach(b=>b.onclick=()=>{const a=b.dataset.speech;if(a==='pause')return pauseSpeech();if(a==='resume')return resumeSpeech();if(a==='stop')return stopSpeech();const t=getText(a);if(t)speak(t);});}
function slideText(slide,type){return RT.ppt?.[Math.max(0,slide-1)]?.[type]||'';}

/* question engine */
function createQState(q,order=null){return{order:order||shuffleIndices(q.options.length),selected:null,firstWrong:null,phase:'select1'};}
function questionDone(s){return s.phase==='correct'||s.phase==='route';}
function feedbackGrid(items){return `<div class="feedback-grid">${items.map(x=>`<div><strong>${esc(x[0])}</strong><p>${esc(x[1])}</p></div>`).join('')}</div>`;}
function renderQuestion(host,q,s,cfg={}){
  const locked=s.phase==='firstWrong'||questionDone(s);
  const opts=s.order.map((orig,pos)=>{const [text,ok]=q.options[orig],selected=s.selected===orig,firstWrong=s.firstWrong===orig,route=s.phase==='route';return `<button type="button" class="${['option',selected?'selected':'',firstWrong?'wrong-choice':'',route&&ok?'correct-choice':''].filter(Boolean).join(' ')}" data-opt="${orig}" ${(locked||(s.phase==='select2'&&firstWrong))?'disabled':''}><strong>${String.fromCharCode(65+pos)}.</strong> ${esc(text)}</button>`;}).join('');
  let feedback='';
  if(s.phase==='correct')feedback=`<div class="feedback good" data-feedback><div class="feedback-title"><span>✓</span><div><h4>Respuesta correcta</h4><p>Revisa el razonamiento, no solo el resultado.</p></div></div><p class="feedback-main">${esc(q.correct)}</p>${feedbackGrid([['Por qué es correcta',q.correct],['Cómo se aplica',q.application],['Por qué no las otras',q.contrast],['Regla transferible',q.rule]])}</div>`;
  else if(s.phase==='firstWrong'){const chosen=q.options[s.firstWrong]?.[0]||'';feedback=`<div class="feedback bad" data-feedback><div class="feedback-title"><span>↺</span><div><h4>Primer intento incorrecto</h4><p>Todavía no mostramos la respuesta correcta.</p></div></div><p class="feedback-main">${esc(q.wrong1)}</p>${feedbackGrid([['Tu elección',chosen],['Qué revisar','Distingue cálculo, composición, contexto y riesgo antes de volver a elegir.'],['Pista',q.rule],['Segundo intento','Pulsa “Cambiar respuesta · segundo intento”. La alternativa anterior quedará bloqueada.']])}</div>`;}
  else if(s.phase==='route'){const correct=q.options.find(x=>x[1])?.[0]||'';feedback=`<div class="feedback route" data-feedback><div class="feedback-title"><span>→</span><div><h4>Ruta correcta</h4><p>El segundo intento también fue incorrecto. Reconstruimos el criterio paso a paso.</p></div></div><p class="feedback-main">${esc(q.routeSummary)}</p><ol class="route-steps">${(q.route||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${feedbackGrid([['Alternativa defendible',correct],['Por qué corresponde',q.correct],['Aplicación',q.application],['Por qué se descartan las otras',q.contrast],['Regla que debes conservar',q.rule]])}</div>`;}
  const label=s.phase==='select1'?'Intento 1 de 2':s.phase==='firstWrong'?'Primer intento revisado':s.phase==='select2'?'Intento 2 de 2':s.phase==='correct'?'Pregunta completada':'Ruta correcta';
  const actions=s.phase==='select1'||s.phase==='select2'?`<button class="btn primary" data-check ${s.selected===null?'disabled':''}>Comprobar respuesta</button>`:s.phase==='firstWrong'?`<button class="btn orange" data-change>Cambiar respuesta · segundo intento</button>`:'';
  host.innerHTML=`<div class="qbox"><div class="qmeta"><span class="attempt-badge">${label}</span></div><div class="question-prompt"><span class="question-label">PREGUNTA</span><p>${esc(q.text||q.question||'')}</p></div><div class="options">${opts}</div><div class="qactions">${actions}</div>${feedback}</div>`;
  $$('[data-opt]',host).forEach(b=>b.onclick=()=>{if(locked)return;s.selected=Number(b.dataset.opt);beep('soft');renderQuestion(host,q,s,cfg);});
  $('[data-check]',host)?.addEventListener('click',()=>{if(s.selected===null)return;const ok=!!q.options[s.selected][1];if(ok){s.phase='correct';beep('ok');renderQuestion(host,q,s,cfg);setTimeout(()=>$('[data-feedback]',host)?.scrollIntoView({behavior:'smooth',block:'nearest'}),30);cfg.onFinish?.({correct:true});}else if(s.phase==='select1'){s.firstWrong=s.selected;s.phase='firstWrong';beep('bad');renderQuestion(host,q,s,cfg);setTimeout(()=>$('[data-feedback]',host)?.scrollIntoView({behavior:'smooth',block:'nearest'}),30);}else{const correctIdx=q.options.findIndex(x=>x[1]);s.selected=correctIdx;s.phase='route';beep('bad');renderQuestion(host,q,s,cfg);setTimeout(()=>$('[data-feedback]',host)?.scrollIntoView({behavior:'smooth',block:'nearest'}),30);cfg.onFinish?.({correct:false});}});
  $('[data-change]',host)?.addEventListener('click',()=>{s.selected=null;s.phase='select2';beep('soft');renderQuestion(host,q,s,cfg);});
}

/* concepts */
function conceptState(c){if(!state.concepts[c.id]){const i=DATA.concepts.indexOf(c);state.concepts[c.id]={openQ:false,q:createQState(c,orderWithTarget(c,conceptCorrectPositions[i]))};}return state.concepts[c.id];}
function renderConceptCards(){const host=$('#conceptGrid');host.innerHTML=DATA.concepts.map((c,i)=>{const s=conceptState(c),done=questionDone(s.q);return `<article class="concept-card" tabindex="0" data-concept="${i}"><div class="concept-card-inner"><div class="concept-face concept-front">${done?'<span class="concept-status">✓ Revisada</span>':''}<div class="concept-slide-thumb"><img src="assets/ppt/slide-${String(c.slide).padStart(2,'0')}.png" alt="${esc(c.title)}"></div><div class="concept-front-copy"><span class="concept-number">${c.number}</span><h3>${esc(c.title)}</h3><p>${esc(c.short)}</p><small>Pasa el mouse para ver el resumen · clic para abrir</small></div></div><div class="concept-face concept-back"><span class="concept-number">${c.number}</span><h3>${esc(c.title)}</h3><p>${esc(c.meaning)}</p><div class="open-cue">Haz clic para abrir →</div></div></div></article>`;}).join('');$$('[data-concept]',host).forEach(card=>{const fn=()=>openConcept(Number(card.dataset.concept));card.onclick=fn;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn();}};});const done=DATA.concepts.filter(c=>questionDone(conceptState(c).q)).length;$('#conceptProgress').textContent=`${done} / ${DATA.concepts.length} revisadas`;}
function openConcept(i){conceptIndex=Math.max(0,Math.min(DATA.concepts.length-1,i));renderConceptModal();openDialog('conceptModal');setTimeout(()=>$('#conceptBody').scrollTo({top:0}),20);}
function renderConceptModal(){const c=DATA.concepts[conceptIndex],s=conceptState(c),slide=`assets/ppt/slide-${String(c.slide).padStart(2,'0')}.png`;$('#conceptKicker').textContent=`Tarjeta ${c.number} · concepto aplicado`;$('#conceptTitle').textContent=c.title;$('#conceptCounter').textContent=`${conceptIndex+1} / ${DATA.concepts.length}`;$('#prevConcept').disabled=conceptIndex===0;$('#nextConcept').disabled=conceptIndex===DATA.concepts.length-1;const qp=s.openQ?'<div id="conceptQuestion"></div>':`<div class="question-gate"><div><strong>¿Listo para comprobar?</strong><span>Revisa primero el concepto, el apoyo visual y la cápsula de audio.</span></div><button class="btn primary" data-show-question>Ver pregunta →</button></div>`;let extra='';if(c.id==='radiografia')extra=`<div class="actions"><button class="btn orange" data-open-resource="video-short">▶ Ver video corto · evaluación bancaria</button><button class="btn secondary" data-open-resource="ppt" data-resource-index="4">Ver resultados y flujo</button></div>`;if(c.id==='ratios')extra=`<div class="actions"><button class="btn secondary" data-open-resource="ppt" data-resource-index="6">Ver liquidez y endeudamiento</button><button class="btn secondary" data-go-lab>Ir al laboratorio de ratios</button></div>`;if(c.id==='rentabilidad')extra=`<div class="actions"><button class="btn secondary" data-open-resource="ppt" data-resource-index="7">Ver rentabilidad y eficiencia</button></div>`;if(c.id==='riesgo')extra=`<div class="actions"><button class="btn secondary" data-open-resource="ppt" data-resource-index="13">Ver inherente → residual</button><button class="btn secondary" data-open-resource="infographic">Ver infografía integradora</button></div>`;
  $('#conceptBody').innerHTML=`<div class="concept-modal-layout"><div class="concept-image-column"><img class="concept-main-slide" src="${slide}" alt="Diapositiva de ${esc(c.title)}" data-image="${slide}">${speechControlsHTML()}</div><div class="concept-detail-scroll"><section class="detail-box"><span class="mini-label">QUÉ SIGNIFICA</span><p>${esc(c.meaning)}</p></section><section class="detail-box example"><span class="mini-label">EJEMPLO</span><p>${esc(c.example)}</p></section><section class="detail-box warning"><span class="mini-label">ERROR QUE CONVIENE EVITAR</span><p>${esc(c.error)}</p></section><div class="audio-pista"><strong>🎧 Cápsula del audio antes de responder</strong><p>Extracto breve del audio completo de la sesión.</p><audio controls preload="metadata"><source src="${c.audio}" type="audio/mp4"></audio></div>${extra}${qp}</div></div>`;
  bindSpeechControls($('#conceptBody'),type=>slideText(c.slide,type));$('[data-image]',$('#conceptBody'))?.addEventListener('click',e=>openImage(e.currentTarget.dataset.image,e.currentTarget.alt));$$('[data-open-resource]',$('#conceptBody')).forEach(b=>b.onclick=()=>openResource(b.dataset.openResource,Number(b.dataset.resourceIndex||0)));$('[data-go-lab]',$('#conceptBody'))?.addEventListener('click',()=>{closeDialog('conceptModal');go('simulador');});$('[data-show-question]',$('#conceptBody'))?.addEventListener('click',()=>{s.openQ=true;renderConceptModal();setTimeout(()=>$('#conceptQuestion')?.scrollIntoView({behavior:'smooth',block:'start'}),30);});if(s.openQ)renderQuestion($('#conceptQuestion'),c,s.q,{onFinish:renderConceptCards});}

